#pragma once
#include "color_picker_scheme.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <limits>
#include <vector>
namespace moon {
struct PickerQuantization {int hueSteps=0,colorSteps=0;};
inline constexpr std::array<int,5> pickerHuePresets{{0,6,12,24,36}};
inline constexpr std::array<int,4> pickerColorPresets{{0,5,9,15}};
template<std::size_t N> inline int pickerNearestPreset(double value,const std::array<int,N>& presets){int nearest=presets[0];if(!std::isfinite(value))return nearest;for(int preset:presets)if(std::abs(preset-value)<std::abs(nearest-value))nearest=preset;return nearest;}
inline PickerQuantization pickerNormalizeQuantization(PickerQuantization q){return {pickerNearestPreset(q.hueSteps,pickerHuePresets),pickerNearestPreset(q.colorSteps,pickerColorPresets)};}
inline bool pickerQuantized(PickerQuantization q){return q.hueSteps>0||q.colorSteps>0;}
inline double pickerQuantHue(double hue,PickerQuantization q){return pickerHue(q.hueSteps>0?std::floor(hue/(360./q.hueSteps)+.5)*(360./q.hueSteps):hue);}
inline double pickerQuantColor(double p,PickerQuantization q){p=pickerUnit(p);return q.colorSteps>0?std::min(q.colorSteps-1,int(std::floor(p*q.colorSteps)))/double(q.colorSteps-1):p;}
inline double pickerQuantCell(double p,PickerQuantization q){p=pickerUnit(p);return q.colorSteps>0?(std::min(q.colorSteps-1,int(std::floor(p*q.colorSteps)))+.5)/q.colorSteps:p;}
inline PickerMoonWeights pickerQuantTriangle(PickerMoonWeights w,PickerQuantization q){if(q.colorSteps<=0)return w;const double levels=std::max(1,q.colorSteps-1);std::array<double,3> scaled{{std::max(0.,w.tip)*levels,std::max(0.,w.white)*levels,std::max(0.,w.black)*levels}};std::array<int,3> integer{{int(std::floor(scaled[0])),int(std::floor(scaled[1])),int(std::floor(scaled[2]))}};std::array<int,3> order{{0,1,2}};std::stable_sort(order.begin(),order.end(),[&](int a,int b){return scaled[a]-integer[a]>scaled[b]-integer[b];});const int remaining=int(levels)-integer[0]-integer[1]-integer[2];for(int i=0;i<remaining;++i)++integer[order[i]];return {integer[0]/levels,integer[1]/levels,integer[2]/levels};}
inline PickerWheelPoint pickerQuantWheel(double dx,double dy,PickerQuantization q,double safe=1){if(q.colorSteps>0){dx=pickerQuantCell((dx+1)/2,q)*2-1;dy=pickerQuantCell((dy+1)/2,q)*2-1;}const double r=std::hypot(dx,dy);if(r>safe&&r>0){dx*=safe/r;dy*=safe/r;}return {dx,dy};}
inline double pickerQuantWheelSafe(PickerQuantization q){return q.colorSteps>0?std::max(.94,1-10./256):1;}
inline PickerHsv pickerQuantInput(ColorPickerScheme scheme,PickerHsv source,double x,double y,PickerQuantization q){if(scheme==ColorPickerScheme::Wheel){auto p=pickerWheelRaw(x,y);double r=std::hypot(p.x,p.y);if(r>1&&r>0){p.x/=r;p.y/=r;}p=pickerQuantWheel(p.x,p.y,q,pickerQuantWheelSafe(q));return {pickerQuantHue(std::atan2(p.y,p.x)*180/pickerWheelPi,q),std::min(1.,std::hypot(p.x,p.y)),source.v};}if(scheme==ColorPickerScheme::NormalMap){auto p=pickerNormalProject((x-.5)*2,(y-.5)*2);auto n=pickerNormalQuantize(p.x,p.y,q.hueSteps,q.colorSteps);return pickerRgbToHsv(pickerNormalMapColorAt(n.x,n.y));}const double xx=pickerQuantColor(x,q),yy=pickerQuantColor(y,q);return scheme==ColorPickerScheme::HsSquare?PickerHsv{pickerQuantHue(xx*360,q),1-yy,source.v}:PickerHsv{source.h,xx,1-yy};}
inline void pickerQuantMoonSample(PickerMoonGesture& gesture,PickerRole& role,PickerMoonField field,double x,double y,PickerQuantization q){x=pickerUnit(x);y=pickerUnit(y);const double dx=(x-.5)*2,dy=(y-.5)*2;if(gesture.zone==PickerMoonGesture::Zone::None){gesture.zone=std::hypot(dx,dy)>=pickerMoonInner?PickerMoonGesture::Zone::Hue:PickerMoonGesture::Zone::Center;gesture.fieldHue=role.hsv.h;}if(gesture.zone==PickerMoonGesture::Zone::Hue)role.hsv.h=pickerQuantHue(std::atan2(dy,dx)*180/pickerMoonPi+pickerMoonRotation,q);else if(field==PickerMoonField::HslTriangle){role.hsv=pickerRgbToHsv(pickerMoonTriangleColor(gesture.fieldHue,pickerQuantTriangle(pickerMoonClosest(x,y),q)));role.hsv.h=pickerHue(gesture.fieldHue);}else{role.hsv.s=pickerQuantColor((dx/pickerMoonSquare+1)/2,q);role.hsv.v=pickerQuantColor(1-pickerUnit((dy/pickerMoonSquare+1)/2),q);}role.emit();}
inline std::pair<double,double> pickerQuantMarker(ColorPickerScheme scheme,PickerHsv source,PickerMoonField moonField,PickerQuantization q){const double hue=pickerQuantHue(source.h,q);if(scheme==ColorPickerScheme::Wheel){const double angle=hue*pickerWheelPi/180;auto p=pickerQuantWheel(std::cos(angle)*source.s,std::sin(angle)*source.s,q,pickerQuantWheelSafe(q));return {pickerWheelInset+(p.x+1)*.5*pickerWheelScale,pickerWheelInset+(p.y+1)*.5*pickerWheelScale};}if(scheme==ColorPickerScheme::NormalMap){auto p=pickerNormalVectorFromColor(pickerHsvToRgb(source));auto n=pickerNormalQuantize(p.x,p.y,q.hueSteps,q.colorSteps);return {pickerWheelInset+(n.x+1)*.5*pickerWheelScale,pickerWheelInset+(n.y+1)*.5*pickerWheelScale};}if(scheme==ColorPickerScheme::MoonRing){if(moonField==PickerMoonField::HslTriangle){const auto w=pickerQuantTriangle(pickerMoonColorWeights(pickerHsvToRgb(source)),q);const auto v=pickerMoonVertices();return {w.tip*v[0].x+w.white*v[1].x+w.black*v[2].x,w.tip*v[0].y+w.white*v[1].y+w.black*v[2].y};}return {(1-pickerMoonSquare)/2+pickerQuantCell(source.s,q)*pickerMoonSquare,(1-pickerMoonSquare)/2+pickerQuantCell(1-source.v,q)*pickerMoonSquare};}return scheme==ColorPickerScheme::HsSquare?std::pair<double,double>{pickerQuantCell(hue/360,q),pickerQuantCell(1-source.s,q)}:std::pair<double,double>{pickerQuantCell(source.s,q),pickerQuantCell(1-source.v,q)};}
struct PickerQuantTriangleGeometry {int width=0,height=0,steps=-1;std::vector<PickerMoonWeights> weights;std::vector<unsigned char> inside;void ensure(int w,int h,PickerQuantization q){if(width==w&&height==h&&steps==q.colorSteps)return;width=w;height=h;steps=q.colorSteps;weights.resize(std::size_t(w)*h);inside.resize(weights.size());for(int y=0;y<h;++y)for(int x=0;x<w;++x){const auto i=std::size_t(y)*w+x;const double xx=double(x)/std::max(1,w-1),yy=double(y)/std::max(1,h-1);weights[i]=pickerQuantTriangle(pickerMoonClosest(xx,yy),q);inside[i]=bool(pickerMoonInside(xx,yy));}}};
inline std::optional<std::uint32_t> pickerQuantFieldPixel(ColorPickerScheme scheme,PickerHsv source,PickerMoonField moonField,double x,double y,PickerQuantization q,const PickerMoonWeights* triangle=nullptr,bool triangleInside=true){if(scheme==ColorPickerScheme::Wheel||scheme==ColorPickerScheme::NormalMap){const double xx=(x-pickerWheelInset)/pickerWheelScale,yy=(y-pickerWheelInset)/pickerWheelScale;if(xx<0||xx>1||yy<0||yy>1)return {};const double dx=(xx-.5)*2,dy=(yy-.5)*2;if(scheme==ColorPickerScheme::NormalMap){if(std::hypot(dx,dy)>1)return {};const auto n=pickerNormalQuantize(dx,dy,q.hueSteps,q.colorSteps);return pickerNormalMapColorAt(n.x,n.y);}const auto p=pickerQuantWheel(dx,dy,q,std::numeric_limits<double>::infinity());const double r=std::hypot(p.x,p.y);if(r>1)return {};return pickerHsvToRgb({pickerQuantHue(std::atan2(p.y,p.x)*180/pickerWheelPi,q),std::min(1.,r),source.v});}if(scheme==ColorPickerScheme::MoonRing){const double dx=(x-.5)*2,dy=(y-.5)*2,r=std::hypot(dx,dy);if(r>=pickerMoonInner&&r<=1)return {};if(moonField==PickerMoonField::HslTriangle){if(!triangleInside||(!triangle&&!pickerMoonInside(x,y)))return {};const auto w=triangle?*triangle:pickerQuantTriangle(pickerMoonClosest(x,y),q);return pickerHsvToRgb(pickerRgbToHsv(pickerMoonTriangleColor(source.h,w)));}if(std::abs(dx)>pickerMoonSquare||std::abs(dy)>pickerMoonSquare)return {};return pickerHsvToRgb({source.h,pickerQuantColor((dx/pickerMoonSquare+1)/2,q),pickerQuantColor(1-pickerUnit((dy/pickerMoonSquare+1)/2),q)});}const double xx=pickerQuantColor(x,q),yy=pickerQuantColor(y,q);return pickerHsvToRgb(scheme==ColorPickerScheme::HsSquare?PickerHsv{pickerQuantHue(xx*360,q),1-yy,source.v}:PickerHsv{source.h,xx,1-yy});}
inline bool pickerQuantWheelBeginHit(double x,double y,PickerQuantization q){const auto raw=pickerWheelRaw(x,y);if(std::hypot(raw.x,raw.y)>1)return false;const double ix=std::clamp(std::floor((raw.x+1)*.5*255+.5),0.,255.),iy=std::clamp(std::floor((raw.y+1)*.5*255+.5),0.,255.);return bool(pickerQuantFieldPixel(ColorPickerScheme::Wheel,{0,1,1},PickerMoonField::HsvSquare,ix/255,iy/255,q));}
inline void pickerQuantOutline(std::vector<std::uint32_t>& pixels,const std::vector<unsigned char>& mask,int width,int height){for(int y=0;y<height;++y)for(int x=0;x<width;++x){const auto index=std::size_t(y)*width+x;if(mask[index])continue;std::size_t neighbor=mask.size();for(int oy=-1;oy<=1&&neighbor==mask.size();++oy){const int yy=y+oy;if(yy<0||yy>=height)continue;for(int ox=-1;ox<=1;++ox){if(ox==0&&oy==0)continue;const int xx=x+ox;if(xx<0||xx>=width)continue;const auto candidate=std::size_t(yy)*width+xx;if(mask[candidate]){neighbor=candidate;break;}}}if(neighbor==mask.size())continue;const auto c=pixels[neighbor];const double luminance=(c&255)*.2126+((c>>8)&255)*.7152+((c>>16)&255)*.0722;const std::uint32_t shade=luminance<145?224:20;pixels[index]=shade|(shade<<8)|(shade<<16)|0xff000000u;}}
inline std::vector<std::uint32_t> pickerQuantRaster(ColorPickerScheme scheme,PickerHsv source,PickerMoonField moonField,int width,int height,PickerQuantization q,PickerQuantTriangleGeometry* geometry=nullptr){if(geometry&&scheme==ColorPickerScheme::MoonRing&&moonField==PickerMoonField::HslTriangle)geometry->ensure(width,height,q);std::vector<std::uint32_t> pixels(std::size_t(width)*height);std::vector<unsigned char> mask(pixels.size());for(int y=0;y<height;++y)for(int x=0;x<width;++x){const auto i=std::size_t(y)*width+x;const bool triangle=geometry&&scheme==ColorPickerScheme::MoonRing&&moonField==PickerMoonField::HslTriangle;auto color=pickerQuantFieldPixel(scheme,source,moonField,double(x)/std::max(1,width-1),double(y)/std::max(1,height-1),q,triangle?&geometry->weights[i]:nullptr,triangle?geometry->inside[i]!=0:true);if(color){pixels[i]=*color;mask[i]=1;}}if(q.colorSteps>0&&(scheme==ColorPickerScheme::Wheel||scheme==ColorPickerScheme::NormalMap))pickerQuantOutline(pixels,mask,width,height);return pixels;}
inline std::uint32_t pickerQuantRingColor(double x,double y,PickerQuantization q){const auto base=pickerMoonRingColor(x,y);const int alpha=base>>24;if(!alpha)return 0;return pickerHsvToRgb({pickerQuantHue(std::atan2((y-.5)*2,(x-.5)*2)*180/pickerMoonPi+pickerMoonRotation,q),1,1},alpha);}
inline std::uint32_t pickerQuantStripColor(ColorPickerScheme scheme,PickerHsv hsv,double p,PickerQuantization q){if(pickerSchemeUsesValue(scheme))return pickerHsvToRgb({hsv.h,hsv.s,pickerQuantColor(p,q)});return pickerHsvToRgb({q.hueSteps>0?pickerQuantHue(pickerUnit(p)*360,q):pickerUnit(p)*359,1,1});}
inline double pickerQuantStripFraction(ColorPickerScheme scheme,PickerHsv hsv,PickerQuantization q){return pickerSchemeUsesValue(scheme)?pickerQuantCell(hsv.v,q):pickerQuantHue(hsv.h,q)/359;}
inline int pickerQuantStripValue(ColorPickerScheme scheme,PickerHsv hsv,PickerQuantization q){return int(std::floor((pickerSchemeUsesValue(scheme)?pickerQuantCell(hsv.v,q)*1000:pickerQuantHue(hsv.h,q))+.5));}
inline int pickerQuantAlphaValue(std::uint32_t color,PickerQuantization q){return int(std::floor(pickerQuantCell(double(color>>24)/255,q)*255+.5));}
inline void pickerQuantSetStrip(PickerRole& role,ColorPickerScheme scheme,double p,PickerQuantization q){if(pickerSchemeUsesValue(scheme)){role.hsv.v=pickerQuantColor(p,q);role.emit();}else role.hue(pickerQuantHue(pickerUnit(p)*359,q));}
inline void pickerQuantSetStripValue(PickerRole& role,ColorPickerScheme scheme,int value,PickerQuantization q){if(pickerSchemeUsesValue(scheme)){role.hsv.v=pickerQuantColor(double(value)/1000,q);role.emit();}else role.hue(pickerQuantHue(std::clamp(value,0,359),q));}
inline void pickerQuantSetAlphaValue(PickerRole& role,int value,PickerQuantization q){role.alpha(pickerQuantColor(double(value)/255,q)*255);}
}
